// The assembler must produce the same bytes as GNU as + ld for every source in gnu-asm.json
// (generated by sim/golden/gen_asm_fixtures.py with riscv-none-elf-gcc -mno-relax and sw/link.ld).
import { describe, expect, it } from "vitest";
import { assemble } from "../assembler";
import fixtures from "./gnu-asm.json";

const hex = (bytes: Uint8Array) => Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
const imemBytes = (words: Uint32Array) => {
  const b = new Uint8Array(words.length * 4);
  words.forEach((w, i) => {
    b[4 * i] = w & 0xff;
    b[4 * i + 1] = (w >>> 8) & 0xff;
    b[4 * i + 2] = (w >>> 16) & 0xff;
    b[4 * i + 3] = (w >>> 24) & 0xff;
  });
  return b;
};

const table = fixtures as Record<string, { source: string; text: string; data: string }>;

describe("assembler vs GNU as/ld", () => {
  it.each(Object.keys(table))("%s", (name) => {
    const gnu = table[name] as { source: string; text: string; data: string };
    const ours = assemble(gnu.source);
    expect(ours.errors).toEqual([]);
    expect(ours.textBytes).toBe(gnu.text.length / 2);
    expect(hex(imemBytes(ours.imem).subarray(0, ours.textBytes))).toBe(gnu.text);
    expect(hex(ours.imem.length ? imemBytes(ours.imem).subarray(ours.textBytes) : new Uint8Array())).toBe(
      "00".repeat(imemBytes(ours.imem).length - ours.textBytes),
    );
    expect(ours.dataBytes).toBe(gnu.data.length / 2);
    expect(hex(ours.dmem.subarray(0, ours.dataBytes))).toBe(gnu.data);
  });

  it("covers the presets, the macro programs and the snippets", () => {
    const names = Object.keys(table);
    expect(names.filter((n) => n.startsWith("preset/"))).toHaveLength(5);
    expect(names.filter((n) => n.startsWith("sim_programs/"))).toHaveLength(5);
    expect(names.filter((n) => n.startsWith("snippet/")).length).toBeGreaterThanOrEqual(16);
  });
});
